P.entries["item:final-message-to-the-wildhammer"] = {n="Ultimo Messaggio per i Granmartello",s="L'Ultimo Messaggio per i Granmartello è una lancia che Otho Moji'ko invia dal Villaggio degli Zannatorta al Picco dell'Aquila. La macabra messinscena vuole mostrare ai nani Granmartello che i troll fanno sul serio.",h="L'Ultimo Messaggio per i Granmartello è una lancia che Otho Moji'ko invia dal Villaggio degli Zannatorta al...",kw={"picco dell'aquila","ultimo messaggio","piume di grifone","otho moji'ko","villaggio degli zannatorta","lancia","pozzo","granmartello"},ang={["faction:Alliance"]="Per l'Alleanza, la lancia è una minaccia diretta piantata nel cuore del Picco dell'Aquila, tra i nani Granmartello.",["race:Troll"]="Da troll, porti la minaccia di Otho Moji'ko nel Picco dell'Aquila, dove spera che i nani Granmartello vedano la forza degli Zannatorta."},sec={{t="Una lancia per il Picco dell'Aquila",b="Al Villaggio degli Zannatorta, negli Entroterre, Otho Moji'ko ti consegna una lancia intrisa di sangue e avvolta in piume di grifone. Vuole che la pianti vicino al pozzo al centro del Picco dell'Aquila, dove la vedranno i nani Granmartello. Il messaggio è chiaro, e Otho spera che tu torni vivo."}},faq={{q="Cos'è l'Ultimo Messaggio per i Granmartello?",a="È una lancia intrisa di sangue e avvolta in piume di grifone, inviata da Otho Moji'ko al Picco dell'Aquila.",al={"ultimo messaggio","lancia dei granmartello","messaggio di otho"}},{q="Chi ti consegna la lancia?",a="Otho Moji'ko ti consegna la lancia al Villaggio degli Zannatorta, negli Entroterre.",al={"chi è otho","chi la consegna","troll che consegna la lancia"}},{q="Dove va piantata la lancia?",a="Otho vuole che tu la pianti vicino al pozzo al centro del Picco dell'Aquila.",al={"dove piantarla","pozzo del picco dell'aquila","dov'è il messaggio"}},{q="Perché inviare una lancia insanguinata?",a="Otho vuole che i nani Granmartello vedano che i troll fanno sul serio.",al={"perché la lancia","cosa significa","i troll fanno sul serio"}},{q="Cosa succede quando la pianti?",a="Quando pianti la lancia, Falstad Granmartello urla e vieni contrassegnato per il PvP.",al={"urlo di falstad","posare il messaggio","reazione dei granmartello"}}},fp="31,193,22.278.0,44.93.0,24.73.0,24.67.0,24.71.0,31.78.0"}
