P.entries["item:firebeard-s-head"] = {n="Testa di Barbafiamma",s="La testa di Andre Firebeard è la prova richiesta dal mandato al Porto degli Spargifumo. La legge del porto consente che la sua testa lo rappresenti al processo.",h="La testa di Andre Firebeard è la prova richiesta dal mandato al Porto degli Spargifumo.",kw={"andre firebeard","testa di barbafiamma","meccania","pirata","capo della sorveglianza segachiodi","porto degli spargifumo","tanaris","ricercato"},sec={{t="Un mandato vincolante",b="Il Capo della Sorveglianza Segachiodi accetta la testa di Andre Firebeard in sua vece all’udienza. Il mandato accusa il pirata di crimini contro Steamwheedle e Meccania. Quando porti la testa al porto, Segachiodi considera adempiuto il contratto e ti offre una ricompensa per il servizio."}},faq={{q="Perché il mandato chiede la sua testa?",a="Il mandato dice che la testa di Andre Firebeard può rappresentarlo se è morto o impossibilitato a presentarsi all’udienza. Il Capo della Sorveglianza Segachiodi la accetta al Porto degli Spargifumo.",al={"mandato per la testa di andre","perché la sua testa","testa di firebeard"}},{q="Chi è Andre Firebeard?",a="Andre Firebeard è un pirata ricercato per crimini contro Steamwheedle e Meccania.",al={"andre firebeard","pirata firebeard","chi è andre"}},{q="Chi prende la testa di Firebeard?",a="Il Capo della Sorveglianza Segachiodi prende la testa di Andre Firebeard al Porto degli Spargifumo.",al={"chi vuole la testa","testa segachiodi","dove portare la testa di andre"}},{q="Dov’è il Porto degli Spargifumo?",a="Il Porto degli Spargifumo si trova sulla costa di Tanaris. Il mandato contro Andre Firebeard è affisso lì.",al={"posizione di steamwheedle","porto di tanaris","dov’è il porto"}}},fp="16,157,17.284.0,38.172.0,23.81.0,29.80.0,27.92.0"}
