P.entries["item:forked-mudrock-tongue"] = {n="Lingua di Roccialorda Biforcuta",s="Le Forked Mudrock Tongues provengono dalle tartarughe Mudrock lungo la costa di Acquemorte. Morgan Stern le vuole per una nuova zuppa da servire a Roccavento.",h="Le Forked Mudrock Tongues provengono dalle tartarughe Mudrock lungo la costa di Acquemorte.",kw={"blue recluse","acquemorte","lingua di roccialorda biforcuta","morgan stern","mudrock soup and bugs","mudrock tongue","tartaruga mudrock","theramore"},ang={["profession:Cooking"]="Da cuoco, potresti chiederti quale sapore Morgan speri di ricavare da queste lingue. Sta sperimentando tecniche per esaltarne il gusto particolare nel suo Mudrock Soup and Bugs."},sec={{t="La richiesta di un cuoco",b="Morgan Stern cerca Forked Mudrock Tongues a Theramore. Crede che abbiano un sapore particolare e vuole provarle nel suo Mudrock Soup and Bugs. Le tartarughe vivono lungo la costa, soprattutto intorno alla baia."}},faq={{q="Da dove provengono le Forked Mudrock Tongues?",a="Provengono dalle tartarughe Mudrock lungo la costa di Acquemorte, soprattutto intorno alla baia.",al={"provenienza mudrock tongue","dove trovare la lingua","dove trovare le lingue biforcute"}},{q="Perché Morgan Stern le vuole?",a="Morgan Stern vuole provare il loro sapore particolare nel suo Mudrock Soup and Bugs.",al={"perché morgan vuole le lingue","ricetta di morgan","zuppa e insetti"}},{q="Chi è Morgan Stern?",a="Morgan Stern è un cuoco di Theramore al lavoro su un piatto chiamato Mudrock Soup and Bugs.",al={"chi è morgan stern","chi è morgan","cuoco di theramore"}},{q="Dove spera di servire il piatto Morgan?",a="Morgan spera di servire Mudrock Soup and Bugs al Blue Recluse di Roccavento.",al={"dove servire la zuppa","piatto del blue recluse","ristorante di roccavento"}}},fp="21,156,18.209.0,42.90.0,32.78.0,20.83.0,41.77.0"}
