P.entries["item:frozen-ectoplasm"] = {n="Ectoplasma Congelato",s="Mux Turbamana ha bisogno dell’Ectoplasma Congelato degli spiriti inquieti dei Highborne di Fontefredda. È una delle tre sostanze spettrali che cerca per il suo lavoro con i morti.",h="Mux Turbamana ha bisogno dell’Ectoplasma Congelato degli spiriti inquieti dei Highborne di Fontefredda.",kw={"anguished highborne","ectoplasma","distillatore ectoplasmatico","ectoplasma congelato","hunting for ectoplasm","mux turbamana","suffering highborne","fontefredda"},ang={["profession:Engineering"]="Se sei un ingegnere, potresti riconoscere il Distillatore Ectoplasmatico di Mux: è il suo dispositivo per raccogliere sostanze spettrali."},sec={{t="Spiriti invernali",b="Vicino al lago di Fontefredda, gli Anguished e i Suffering Highborne lasciano Ectoplasma Congelato. Mux Turbamana ti chiede di raccoglierlo con un Distillatore Ectoplasmatico, insieme all’Ectoplasma Bruciato di Silitus e all’Ectoplasma della Scuderia delle Terre Infette Orientali. Spera che le tre sostanze gli permettano di raggiungere le anime che non hanno ancora lasciato del tutto questo mondo."}},faq={{q="Dove trovo l’Ectoplasma Congelato?",a="Gli Anguished e i Suffering Highborne vicino al lago di Fontefredda lasciano Ectoplasma Congelato.",al={"posizione dell’ectoplasma congelato","dove trovare l’ectoplasma congelato","ectoplasma a fontefredda"}},{q="A cosa serve l’Ectoplasma Congelato?",a="Serve a Mux Turbamana per Hunting for Ectoplasm, che richiede tre tipi di ectoplasma raccolti con un Distillatore Ectoplasmatico.",al={"uso dell’ectoplasma congelato","a cosa serve","scopo dell’ectoplasma"}},{q="Chi cerca l’Ectoplasma Congelato?",a="Mux Turbamana, a Meccania, cerca Ectoplasma Congelato, oltre all’Ectoplasma Bruciato e a quello della Scuderia.",al={"mux ed ectoplasma","chi ne ha bisogno","mux turbamana"}},{q="Perché Mux vuole l’ectoplasma?",a="Mux spera di usare le energie ultraterrene dell’ectoplasma per raggiungere le anime che non hanno ancora lasciato del tutto questo mondo.",al={"perché l’ectoplasma","piano di mux","raggiungere le anime"}},{q="Quali spiriti lasciano Ectoplasma Congelato?",a="Gli spiriti Anguished e Suffering Highborne di Fontefredda lasciano Ectoplasma Congelato.",al={"da cosa si ottiene l’ectoplasma","ectoplasma degli highborne","bottino degli spiriti congelati"}}},fp="16,166,14.350.0,33.94.0,29.134.0,27.96.0,28.112.0,36.85.0"}
