P.entries["item:gadrin-s-parchment"] = {n="Cartapecora di Gadrin",s="La Cartapecora di Gadrin si legge a Shadra'alor, negli Entroterre. Le sue parole evocano Shadra, il cui veleno è cercato dallo Speziale Lydon a Mulino di Tarren.",h="La Cartapecora di Gadrin si legge a Shadra'alor, negli Entroterre.",kw={"speziale lydon","gadrin","cartapecora di gadrin","entroterre","cartapecora","shadra","shadra'alor","veleno","witherbark"},sec={{t="A Shadra'alor",b="Nel profondo del territorio Witherbark, la Cartapecora di Gadrin si legge all'altare di Shadra'alor. Le sue parole evocano Shadra, The Spider God. Il suo veleno è cercato dallo Speziale Lydon a Mulino di Tarren."}},faq={{q="A cosa serve la Cartapecora di Gadrin?",a="La Cartapecora di Gadrin si legge a Shadra'alor per evocare Shadra, The Spider God.",al={"a cosa serve la cartapecora","uso della cartapecora di gadrin"}},{q="Dove leggo la cartapecora?",a="Leggi la Cartapecora di Gadrin all'altare di Shadra'alor, nel profondo del territorio Witherbark negli Entroterre.",al={"dove usare la cartapecora","posizione dell'altare di shadra"}},{q="Chi è Shadra?",a="Shadra è The Spider God, evocata leggendo la Cartapecora di Gadrin a Shadra'alor.",al={"shadra ragno","dio ragno"}},{q="Chi vuole il veleno di Shadra?",a="Lo Speziale Lydon a Mulino di Tarren cerca il veleno di Shadra.",al={"per chi è il veleno","veleno lydon"}}},fp="18,137,14.182.0,32.75.0,30.101.0,14.79.0,25.53.0"}
