P.entries["item:gahz-ridian-detector"] = {n="Rilevatore Gahz'ridian",s="Il Rilevatore Gahz'ridian è un dispositivo ideato da Marvon Cercachiodi per trovare gli ornamenti sparsi per Tanaris. Lo aiuta a raccogliere materiale per i suoi studi sulle incisioni create dai troll.",h="Il Rilevatore Gahz'ridian è un dispositivo ideato da Marvon Cercachiodi per trovare gli ornamenti sparsi per...",kw={"pilastro spezzato","rovine di luna dell'est","gahz'ridian","rilevatore gahz'ridian","ornamento gahz'ridian","gahz'rilla","marvon cercachiodi","rovine di luna del sud","tanaris"},sec={{t="Una ricerca nel deserto",b="Marvon Cercachiodi creò il Rilevatore Gahz'ridian per trovare gli ornamenti scolpiti nel Gahz'ridian. I troll li realizzarono molto tempo fa a immagine di Gahz'rilla, che veneravano come una divinità. Le incisioni si trovano in tutta Tanaris, molte vicino al Pilastro Spezzato, alle Rovine di Luna dell'Est e alle Rovine di Luna del Sud."}},faq={{q="Chi ha creato il Rilevatore Gahz'ridian?",a="Marvon Cercachiodi, scienziato e cacciatore di tesori a Tanaris, ha inventato il Rilevatore Gahz'ridian.",al={"chi ha creato il rilevatore","dispositivo di marvon","inventore del rilevatore"}},{q="Che cosa trova il rilevatore?",a="Il Rilevatore Gahz'ridian aiuta a trovare gli ornamenti scolpiti nel Gahz'ridian, un materiale che prende il nome da Gahz'rilla.",al={"cosa trova il rilevatore","trovare gahz'ridian","scopo del rilevatore"}},{q="Chi ha creato gli ornamenti Gahz'ridian?",a="Molto tempo fa, i troll che un tempo abitavano Tanaris scolpirono gli ornamenti Gahz'ridian.",al={"chi ha creato gli ornamenti","incisioni dei troll","origine degli ornamenti"}},{q="Perché gli ornamenti hanno la forma di Gahz'rilla?",a="Gli ornamenti riproducevano Gahz'rilla, un'idra che i troll veneravano come una divinità.",al={"perché ornamenti di gahz'rilla","incisioni di idre","idolo di gahz'rilla"}},{q="Dove posso trovare gli ornamenti Gahz'ridian?",a="Gli ornamenti Gahz'ridian si trovano in tutta Tanaris, soprattutto nei pressi del Pilastro Spezzato, delle Rovine di Luna dell'Est e delle Rovine di Luna del Sud.",al={"dove trovare gli ornamenti","luoghi del gahz'ridian","ornamenti di tanaris"}}},fp="20,184,15.304.0,34.98.0,28.105.0,35.75.0,45.86.0,39.114.0"}
P.entries["item:gahz-ridian-ornament"] = {n="Ornamento Gahz'ridian",s="Gli ornamenti Gahz'ridian sono reliquie scolpite sparse per Tanaris. Marvon Cercachiodi li studia per trovare indizi sui troll che un tempo vivevano qui.",h="Gli ornamenti Gahz'ridian sono reliquie scolpite sparse per Tanaris.",kw={"pilastro spezzato","rilevatore","rovine di luna dell'est","gahz'ridian","gahz'rilla","marvon cercachiodi","ornamento","rovine di luna del sud","tanaris","troll"},sec={{t="Reliquie scolpite",b="Marvon Cercachiodi cerca ornamenti Gahz'ridian per tutta Tanaris. Dice che i troll che un tempo abitavano questo deserto li scolpirono a immagine di Gahz'rilla, l'idra che veneravano. Gli ornamenti sono fatti di una sostanza che Marvon chiama Gahz'ridian, dal nome della creatura venerata. Ne ha già raccolti alcuni e ne vuole altri per i suoi studi."}},faq={{q="Cosa sono gli ornamenti Gahz'ridian?",a="Gli ornamenti Gahz'ridian sono sculture realizzate dai troll che un tempo vivevano a Tanaris. Rappresentano Gahz'rilla, un'idra venerata dai troll.",al={"gahz'ridian","cos'è gahz'ridian","significato di ornamento"}},{q="Chi vuole gli ornamenti?",a="Marvon Cercachiodi, scienziato e cacciatore di tesori a Tanaris, vuole gli ornamenti Gahz'ridian per i suoi studi.",al={"chi vuole gahz'ridian","ornamenti di marvon","dove portare gli ornamenti"}},{q="Dove posso trovare gli ornamenti Gahz'ridian?",a="Gli ornamenti sono sparsi per Tanaris, soprattutto nei pressi del Pilastro Spezzato, delle Rovine di Luna dell'Est e delle Rovine di Luna del Sud.",al={"luoghi gahz'ridian","dove trovare gli ornamenti","rovine gahz'ridian"}},{q="Cos'è Gahz'rilla?",a="Gahz'rilla è un'idra che i troll di Tanaris veneravano come una divinità. Gli ornamenti sono scolpiti a sua immagine.",al={"significato di gahz'rilla","dio idra","divinità dei troll"}},{q="A cosa serve il rilevatore?",a="Marvon Cercachiodi ha inventato il Rilevatore Gahz'ridian per aiutare a trovare gli ornamenti sparsi per Tanaris.",al={"rilevatore gahz'ridian","cercare ornamenti","come trovare gahz'ridian"}}},fp="20,142,13.341.0,31.135.0,24.108.0,39.112.0,19.108.0,25.106.0"}
