P.entries["item:gan-zulah-s-head"] = {n="Testa di Gan'zulah",s="La Testa di Gan'zulah viene sottratta al capo dei Bloodscalp a Zul'Kunda. A Grom'gol, viene portata a un calderone ribollente durante le ricerche di Yenniku.",h="La Testa di Gan'zulah viene sottratta al capo dei Bloodscalp a Zul'Kunda.",kw={"bloodscalp","calderone","puntascura","gan'zulah","testa di gan'zulah","grom'gol","nimboya","yenniku","zul'kunda"},ang={["faction:Horde"]="In quanto membro dell'Orda, aiuti i Puntascura a Grom'gol a scoprire la verità su Yenniku dai loro nemici Bloodscalp.",["race:Troll"]="In quanto troll, ti trovi nel mezzo del conflitto tra i Puntascura e il clan Bloodscalp, il cui capo è quello di cui Nimboya cerca la testa."},sec={{t="La testa di un capo",b="A Zul'Kunda, nel nord-ovest della Valle di Rovotorto, si cerca la Testa di Gan'zulah insieme a quella di Nezzliok il Terribile. Nimboya ti chiede di portarle entrambe alla Caldera Magmatica del Forte di Grom'gol. I Puntascura sperano che i capi defunti possano rivelare la verità su Yenniku."}},faq={{q="Chi era Gan'zulah?",a="Gan'zulah era il capo dei troll Bloodscalp di Zul'Kunda e un nemico della tribù dei Puntascura.",al={"gan zulah","capo bloodscalp","storia di gan'zulah"}},{q="Da dove viene la Testa di Gan'zulah?",a="La Testa di Gan'zulah viene sottratta a Gan'zulah nelle Rovine di Zul'Kunda, nella Valle di Rovotorto.",al={"provenienza della testa","posizione della testa di gan'zulah","trovare gan'zulah"}},{q="Perché Nimboya vuole la testa?",a="Nimboya vuole che la Testa di Gan'zulah e la Testa di Nezzliok vengano messe nella Caldera Magmatica del Forte di Grom'gol, nella speranza di scoprire la verità su Yenniku.",al={"perché la testa","cosa vuole nimboya","testa per nimboya"}},{q="A cosa serve il calderone?",a="I Puntascura mettono le teste di Gan'zulah e Nezzliok nella Caldera Magmatica, sperando di far parlare i capi defunti di Yenniku.",al={"calderone ribollente","caldera magmatica a grom'gol","a cosa serve il calderone"}},{q="Chi è Yenniku?",a="Yenniku è un troll Puntascura la cui sorte è ancora ignota a Nimboya e al suo popolo.",al={"yenniku","dov'è yenniku","hunt for yenniku"}}},fp="16,150,14.262.0,18.95.0,38.89.0,31.146.0,25.125.1,15.82.0"}
