P.entries["item:ghost-o-plasm"] = {n="Plasma Spettrale",s="Il Ghost-o-Plasm è energia spettrale raccolta dagli Magrami Spectres a Desolanda. Hornizz Scoppiachiavi spera di venderla ai Magram centaurs.",h="Il Ghost-o-Plasm è energia spettrale raccolta dagli Magrami Spectres a Desolanda.",kw={"energia spettrale","ghost-o-plasm","ghostoplasm","hornizz scoppiachiavi","magnete","magram centaurs","magrami spectres","valle delle ossa"},ang={["faction:Horde"]="Come membro dell'Orda, aiuti Hornizz a negoziare con i Magram centaurs attraverso uno strano scambio di energia spettrale.",["race:Gnome"]="Da gnomo, potresti riconoscere i magneti fantasma di Hornizz come dispositivi ingegnosi, anche se il suo piano dipende da quanto pagheranno i Magram centaurs."},sec={{t="Raccolto nella valle",b="Tra i due grandi scheletri chiamati Dead Goliaths, una Cassa di Magneti Fantasma attira gli Magrami Spectres dalla Valle delle Ossa. È il loro Ghost-o-Plasm che Hornizz Scoppiachiavi vuole. Spera che i Magram centaurs paghino bene, anche se deve ancora convincerli su cosa sia questa strana sostanza."}},faq={{q="Cos'è il Ghost-o-Plasm?",a="Il Ghost-o-Plasm è energia spettrale ricavata dagli Magrami Spectres a Desolanda.",al={"ghost-o-plasm","roba spettrale","cos'è questa melma"}},{q="Dove trovo il Ghost-o-Plasm?",a="Gli Magrami Spectres nella Valle delle Ossa lasciano Ghost-o-Plasm quando vengono attirati da una Cassa di Magneti Fantasma.",al={"dove trovare ghost-o-plasm","ottenere ghost-o-plasm","dove si trova la roba spettrale"}},{q="Chi vuole il Ghost-o-Plasm?",a="Hornizz Scoppiachiavi vuole il Ghost-o-Plasm e spera di venderlo ai Magram centaurs.",al={"chi ha bisogno di ghost-o-plasm","roba di hornizz","vendere energia spettrale"}},{q="Perché Hornizz lo vuole?",a="Hornizz crede che i Magram centaurs paghino bene per l'energia spettrale catturata.",al={"perché hornizz lo vuole","perché raccogliere roba spettrale","energia spettrale dei centauri"}}},fp="13,135,22.304.0,22.72.0,30.99.0,24.81.0,25.77.0"}
