P.entries["item:goggles-of-gem-hunting"] = {n="Occhialini della Caccia alle Gemme",s="Gli Occhialini della Caccia alle Gemme sono un dispositivo gnomesco usato per trovare tesori sotto le acque degli Altopiani d'Arathi. Il loro incanto rivela le gemme sepolte nella pietra sul fondale marino.",h="Gli Occhialini della Caccia alle Gemme sono un dispositivo gnomesco usato per trovare tesori sotto le acque...",kw={"altopiani d'arathi","dottor erbanera","gemme elfiche","baia di faldir","occhialini","occhialini della caccia alle gemme","professor vitestorta","sunken treasure"},ang={["profession:Engineering"]="Da ingegnere, puoi ammirare come gli occhialini del Dottor Erbanera uniscano la costruzione gnomesca all'incanto del Professor Vitestorta.",["race:Gnome"]="Da gnomo, puoi vedere l'ingegno del Dottor Erbanera all'opera in un dispositivo costruito per trovare gemme sotto il mare."},sec={{t="Sotto le onde",b="Al largo della Baia di Faldir, il Dottor Erbanera presta gli Occhialini della Caccia alle Gemme all'equipaggio del Capitano O'Breen. Il Professor Vitestorta potenzia il dispositivo con una pietra incantata, donandogli il potere di individuare le gemme sott'acqua. Il tesoro è rimasto sommerso così a lungo che le sue gemme si sono calcificate in uno spesso strato di pietra. Erbanera chiede che gli occhialini vengano restituiti al termine della ricerca."}},faq={{q="Chi ha costruito gli occhialini?",a="Il Dottor Erbanera ha costruito gli Occhialini della Caccia alle Gemme, e il Professor Vitestorta li ha potenziati con una pietra incantata.",al={"costruttore degli occhialini","chi li ha costruiti","occhialini erbanera"}},{q="A cosa servono gli occhialini?",a="Gli occhialini permettono a chi li indossa di individuare le gemme sotto il mare, anche quando si sono calcificate in uno spesso strato di pietra.",al={"come funzionano gli occhialini","trovare gemme","occhialini per la caccia alle gemme"}},{q="Dove si usano gli occhialini?",a="Gli Occhialini della Caccia alle Gemme si usano per cercare sul fondale marino al largo della Baia di Faldir, negli Altopiani d'Arathi.",al={"dove usare gli occhialini","posizione degli occhialini","occhialini baia di faldir"}},{q="Perché il Capitano O'Breen vuole le gemme?",a="Il Dottor Erbanera ti chiede di trovare le gemme sommerse per il Capitano O'Breen. Il resoconto fornito non dà altre ragioni per l'interesse del Capitano.",al={"il capitano vuole le gemme","perché raccogliere le gemme elfiche","tesoro o'breeen"}}},fp="22,175,17.367.0,21.126.0,23.109.0,27.98.0,39.145.0"}
