P.entries["item:golem-oil"] = {n="Olio di Golem",s="L’Olio di Golem si raccoglie dai golem e dagli elementali della Gorgia Rovente. Velarok Windblade ne ha bisogno per preparare una torcia per le quattro torri di guardia.",h="L’Olio di Golem si raccoglie dai golem e dagli elementali della Gorgia Rovente.",kw={"elementali","fiamma impeccabile","olio di golem","golem","hearts of flame","gorgia rovente","torri di guardia","torch of flawless flame","velarok windblade"},sec={{t="Olio per la torcia",b="Velarok Windblade chiede quattro globi di Olio di Golem nella Gorgia Rovente. Gli servono insieme a quattro Hearts of Flame per forgiare la Torch of Flawless Flame, destinata ad appiccare il fuoco alle quattro torri di guardia. I golem e gli elementali di queste terre sono il primo posto in cui cercare i materiali."}},faq={{q="A cosa serve l’Olio di Golem?",a="Velarok Windblade usa quattro globi di Olio di Golem insieme a quattro Hearts of Flame per forgiare la Torch of Flawless Flame.",al={"uso dell’olio di golem","perché raccogliere l’olio di golem"}},{q="Chi ha bisogno dell’Olio di Golem?",a="Velarok Windblade chiede Olio di Golem nella Gorgia Rovente per forgiare la Torch of Flawless Flame.",al={"chi vuole l’olio","olio di velarok"}},{q="Dove posso trovare l’Olio di Golem?",a="I golem e gli elementali della Gorgia Rovente sono le prime creature da cui cercare l’Olio di Golem.",al={"dove trovare l’olio di golem","fonte dell’olio"}},{q="Quanto Olio di Golem serve a Velarok?",a="Velarok Windblade chiede quattro globi di Olio di Golem.",al={"quanti globi","quantità di olio"}},{q="A cosa serve la Torch of Flawless Flame?",a="La Torch of Flawless Flame è destinata ad appiccare il fuoco alle quattro torri di guardia.",al={"torcia della fiamma impeccabile","scopo della torcia"}}},fp="9,144,17.275.0,22.111.0,20.98.0,27.89.0,37.52.0,48.74.0"}
