P.entries["item:goodsteel-ledger"] = {n="Libro Mastro di Ferrofiz",s="Il Libro Mastro di Ferrofiz è una copia di un elenco conservato nella Gorgia Rovente. Riporta le merci che Krinkle Ferrofiz vuole ricevere a Meccania.",h="Il Libro Mastro di Ferrofiz è una copia di un elenco conservato nella Gorgia Rovente.",kw={"spada di fuoco bilanciata","meccania","libro mastro di ferrofiz","krinkle ferrofiz","ledger from tanaris","cassa in ritardo","gorgia rovente","zampa di cristallo"},sec={{t="Il libro mastro",b="Vicino a una latrina nella Gorgia Rovente si trova il Libro Mastro di Ferrofiz, una copia destinata a Krinkle Ferrofiz a Meccania. Le sue pagine elencano le merci che cerca in diversi luoghi. Portargli il libro mastro dà inizio alla ricerca di ciò che vi è elencato."}},faq={{q="Cos'è il Libro Mastro di Ferrofiz?",a="Il Libro Mastro di Ferrofiz è una copia dell'elenco delle merci richieste da Krinkle Ferrofiz, trovata nella Gorgia Rovente.",al={"libro mastro di ferrofiz","lista di ferrofiz","ledger from tanaris"}},{q="Dove trovo il libro mastro?",a="Il Libro Mastro di Ferrofiz si trova accanto a una latrina nella Gorgia Rovente.",al={"posizione del libro mastro","dov'è il libro mastro di ferrofiz","libro mastro nella gorgia rovente"}},{q="Chi è Krinkle Ferrofiz?",a="Krinkle Ferrofiz è un goblin di Meccania che cerca merci della Gorgia Rovente e di altri luoghi.",al={"krinkle","tipo ferrofiz","chi vuole il libro mastro"}},{q="Cosa elenca il libro mastro?",a="Il libro mastro elenca Solid Crystal Leg Shafts, una Cassa in Ritardo e la Spada di Fuoco Bilanciata di Ferrofiz.",al={"cosa c'è nell'elenco","merci elencate","merci volute da ferrofiz"}},{q="Dove devo portarlo?",a="Porta la copia del libro mastro a Krinkle Ferrofiz a Meccania, poi recupera le merci elencate.",al={"dove portare il libro mastro","portare il libro mastro a krinkle","ferrofiz a meccania"}}},fp="16,131,10.229.0,29.102.0,27.58.0,25.104.0,26.99.0,23.98.0"}
P.entries["item:goodsteel-s-balanced-flameberge"] = {n="Spada di Fuoco Bilanciata di Ferrofiz",s="Goodsteel’s Balanced Flameberge è uno degli oggetti che Krinkle Ferrofiz cerca per il suo lavoro a Tanaris. Le sue tracce conducono dalla Gorgia Rovente alla Palude del Dolore.",h="Goodsteel’s Balanced Flameberge è uno degli oggetti che Krinkle Ferrofiz cerca per il suo lavoro a Tanaris.",kw={"flameberge","meccania","spada di fuoco bilanciata di ferrofiz","jarquia","krinkle ferrofiz","ledger from tanaris","palude del dolore"},sec={{t="Un posto nell’elenco",b="Nella Gorgia Rovente, il registro di Krinkle Ferrofiz indica una flameberge bilanciata tra le merci che vuole gli vengano portate a Meccania. Jarquia, un murloc sulla costa orientale della Palude del Dolore, porta con sé l’arma. Una volta trovata, può essere consegnata a Krinkle insieme alle altre merci dell’elenco."}},faq={{q="Chi vuole la flameberge?",a="Krinkle Ferrofiz, a Meccania, vuole la flameberge bilanciata, indicata nel suo registro.",al={"chi ne ha bisogno","spada di krinkle","chi vuole quest’arma"}},{q="Dove posso trovare Goodsteel’s Balanced Flameberge?",a="Jarquia, un murloc sulla costa orientale della Palude del Dolore, porta con sé Goodsteel’s Balanced Flameberge.",al={"dov’è la flameberge","trova la spada di goodsteel","dov’è jarquia"}},{q="Perché vogliono la flameberge?",a="Krinkle Ferrofiz ha richiesto l’arma come una delle diverse merci indicate nel suo registro.",al={"perché serve a krinkle","a cosa serve","perché prendere questa spada"}},{q="«Flameberge» è scritto correttamente?",a="Il nome usa «flameberge», anche se di solito la parola si scrive «flamberge».",al={"grafia di flamberge","errore di battitura flameberge","è una flamberge"}}},fp="31,162,19.280.0,25.92.0,51.106.0,29.84.0,39.83.0"}
P.entries["item:gordon-s-crate"] = {n="Cassa di Gordon"}
P.entries["item:gordunni-cobalt"] = {n="Cobalto dei Gordunni",s="All’Avamposto dei Gordunni, un bagliore blu nel terreno attira l’attenzione di Orwin Svitarame. Spera che il cobalto sepolto gli frutti un bel prezzo.",h="All’Avamposto dei Gordunni, un bagliore blu nel terreno attira l’attenzione di Orwin Svitarame.",kw={"accampamento mojache","cobalto","feralas","gordunni","cobalto dei gordunni","avamposto dei gordunni","orwin svitarame","badile di orwin"},sec={{t="Blu nella terra",b="Orwin Svitarame è appena arrivato a Feralas e vuole campioni del minerale che gli ogre dei Gordunni seppelliscono al loro avamposto. Ti presta la sua pala e ti indica la strada verso nord dall’Accampamento Mojache. Cerca il bagliore blu tra i cumuli di terra; Orwin vuole il cobalto per il suo valore sul mercato."}},faq={{q="Chi vuole il Cobalto dei Gordunni?",a="Orwin Svitarame all’Accampamento Mojache vuole dodici campioni di Cobalto dei Gordunni.",al={"chi vuole il cobalto","orwin e il cobalto","minerale di svitarame"}},{q="Dove posso trovare il Cobalto dei Gordunni?",a="Il Cobalto dei Gordunni si trova nei cumuli di terra all’Avamposto dei Gordunni, a nord dell’Accampamento Mojache, a Feralas.",al={"luogo del cobalto","dove trovare il cobalto","terra blu"}},{q="Perché il cobalto è sepolto?",a="Gli ogre dei Gordunni seppelliscono il minerale per impedire agli altri di metterci le mani sopra.",al={"perché è sepolto","gli ogre seppelliscono il cobalto","terra dei gordunni"}},{q="A cosa serve il cobalto a Orwin?",a="Orwin spera di trovare qualcuno disposto a pagare un bel prezzo per il cobalto.",al={"perché orwin lo vuole","prezzo del cobalto","vendere il cobalto"}}},fp="15,127,16.277.0,30.71.0,33.85.0,25.82.0,36.69.0"}
P.entries["item:gordunni-orb"] = {n="Globo Gordunni",s="Il Globo Gordunni è un potente oggetto magico sottratto ai Gordunni a Feralas. La sua magia potrebbe aiutare a svelare lo scopo del loro Dark Ceremony.",h="Il Globo Gordunni è un potente oggetto magico sottratto ai Gordunni a Feralas.",kw={"accampamento mojache","dark ceremony","darkbriar lodge","feralas","gordunni","globo gordunni","signore mago","rok orhan","uthel'nay"},ang={["class:Mage"]="Da mago, puoi capire perché Rok Orhan cerca il globo: la sua magia potrebbe aiutare a saperne di più sul ceremony dei Gordunni.",["faction:Horde"]="In quanto membro dell'Orda, puoi aiutare Rok Orhan dell'Accampamento Mojache a saperne di più sui Gordunni e a pianificarne la caduta."},sec={{t="Il globo di un mago",b="Rok Orhan, all'Accampamento Mojache, cerca un Globo Gordunni per saperne di più sui Gordunni e sulla loro magia. Il globo si ottiene da uno dei signori maghi Gordunni. Il suo potere potrebbe aiutare a scoprire lo scopo del loro Dark Ceremony."},{t="A Orgrimmar",b="Rok Orhan invia il Globo Gordunni a Uthel'nay, alla Darkbriar Lodge di Orgrimmar. Uthel'nay ne riconosce il grande potere e avverte che è pericoloso."}},faq={{q="Cos'è il Globo Gordunni?",a="Il Globo Gordunni è un potente oggetto magico custodito dai signori maghi Gordunni a Feralas.",al={"globo gordunni","quale globo","globo del mago"}},{q="Chi vuole il globo?",a="Rok Orhan, all'Accampamento Mojache, cerca il globo per saperne di più sui Gordunni e sulla loro magia.",al={"chi vuole il globo","globo di rok orhan","globo dell'accampamento mojache"}},{q="A cosa serve il globo?",a="Rok Orhan spera che il potere del globo aiuti a svelare di più sul Dark Ceremony dei Gordunni.",al={"scopo del globo","perché serve il globo","cosa fa"}},{q="Chi può esaminare il globo?",a="Uthel'nay, alla Darkbriar Lodge di Orgrimmar, può dirti di più sul globo.",al={"chi esamina il globo","uthel'nay","mago del globo"}},{q="Perché il globo è pericoloso?",a="Uthel'nay dice che il Globo Gordunni è molto potente e pericoloso.",al={"pericolo del globo","globo pericoloso","è potente"}}},fp="12,141,12.213.0,12.147.0,25.85.0,18.89.0,25.89.0,24.70.0,25.63.0"}
P.entries["item:gorishi-queen-brain"] = {n="Cervello della Regina Gorishi",s="Il Cervello della Regina Gorishi è un campione prelevato dalla regina nell'Anfratto Brulicante. A Meccania, i ricercatori vogliono studiarlo per capire i silitidi e la forza che forse li controlla.",h="Il Cervello della Regina Gorishi è un campione prelevato dalla regina nell'Anfratto Brulicante.",kw={"meccania","gorishi","gorishi hive queen","cervello della regina gorishi","cristallo dell'alveare","intelligenza maligna","silitidi","anfratto brulicante","cratere di un'goro"},sec={{t="Una mente da studiare",b="I ricercatori di Meccania cercano il Cervello della Regina Gorishi dopo aver evocato la Gorishi Hive Queen dalla sua camera, nel sud del Cratere di Un'Goro. Sospettano che i silitidi possano obbedire a un'intelligenza maligna e sperano che il cervello della regina li aiuti a capirla. Le loro scoperte potrebbero svelare qualcosa in più sull'alveare, oltre a ciò che rivela la sola regina."}},faq={{q="Cos'è il Cervello della Regina Gorishi?",a="Il Cervello della Regina Gorishi è un campione prelevato dalla Gorishi Hive Queen per essere studiato dai ricercatori di Meccania.",al={"cervello della regina","cervello gorishi","cos'è questo cervello"}},{q="Da dove viene il Cervello della Regina Gorishi?",a="Viene dalla Gorishi Hive Queen, nell'Anfratto Brulicante, nel sud del Cratere di Un'Goro.",al={"da dove viene il cervello","luogo del cervello della regina","regina gorishi"}},{q="Perché i ricercatori vogliono il cervello della regina?",a="I ricercatori di Meccania sperano che il cervello li aiuti a capire i silitidi e l'intelligenza maligna che, secondo i loro sospetti, potrebbe controllarli.",al={"perché serve il cervello","a cosa serve il cervello","studiare la regina"}},{q="Come viene evocata la Gorishi Hive Queen?",a="Si pensa che usare un'Esca della Regina Gorishi su un cristallo negli incubatoi dell'alveare attiri fuori la regina.",al={"evocare la regina","esca gorishi","come far uscire la regina"}},{q="La regina è l'unica presenza silitide?",a="I ricercatori dubitano che la Gorishi Hive Queen rappresenti l'intera presenza dei silitidi.",al={"altri silitidi","ci sono ancora silitidi","è tutto qui"}}},fp="19,174,15.327.0,32.110.0,45.88.0,42.137.0,39.95.0,40.97.0"}
P.entries["item:gorishi-queen-lure"] = {n="Esca della Regina Gorishi",s="L'Esca della Regina Gorishi è uno strumento usato per attirare la Gorishi Hive Queen fuori dalla sua camera nel Cratere di Un'Goro. I ricercatori di Meccania hanno bisogno del cervello della regina per studiare i silitidi.",h="L'Esca della Regina Gorishi è uno strumento usato per attirare la Gorishi Hive Queen fuori dalla sua camera...",kw={"meccania","gorishi","gorishi hive","esca della regina gorishi","cristallo dell'alveare","regina","cervello della regina","silitidi","cratere di un'goro"},sec={{t="Un alveare in fermento",b="Nel Gorishi Hive del Cratere di Un'Goro, si pensa che un cristallo entri in sintonia con i silitidi attraverso la rete dell'alveare. L'esca viene usata sul cristallo per attirare fuori la regina. I ricercatori di Meccania vogliono studiare il suo cervello, temendo che un'intelligenza maligna possa controllare i silitidi."}},faq={{q="A cosa serve l'Esca della Regina Gorishi?",a="L'Esca della Regina Gorishi si usa su un cristallo nel Gorishi Hive per attirare fuori la Gorishi Hive Queen.",al={"uso dell'esca della regina","a cosa serve l'esca gorishi","come funziona l'esca"}},{q="Dove si usa l'esca?",a="L'esca si usa su un cristallo negli incubatoi del Gorishi Hive, nel Cratere di Un'Goro.",al={"dove usare l'esca della regina","posizione dell'esca","dove si trova il gorishi hive"}},{q="Chi ha fornito l'esca?",a="I ricercatori di Meccania forniscono l'Esca della Regina Gorishi per attirare fuori la regina e studiarla.",al={"chi ha dato l'esca","da dove viene l'esca","esca di meccania"}},{q="Perché i ricercatori vogliono il cervello della regina?",a="I ricercatori hanno bisogno del cervello della Gorishi Hive Queen per studiare i silitidi e indagare se un'intelligenza maligna li controlli.",al={"perché serve il cervello della regina","motivo per il cervello gorishi","a cosa serve il cervello"}},{q="Cos'è il cristallo nell'alveare?",a="Si ritiene che il cristallo entri in sintonia con i silitidi attraverso la rete dell'alveare.",al={"cristallo dell'alveare","cristallo dei silitidi","cosa fa il cristallo"}}},fp="18,175,14.272.0,36.99.0,23.86.0,22.96.0,42.134.0,32.73.0"}
