P.entries["item:green-hills-of-stranglethorn-chapter-i"] = {n="Verdi Colline di Rovotorto - Capitolo I",s="Le pagine sparse di Verdi Colline di Rovotorto sono state raccolte nel Chapter I. Barnil sta riunendo i capitoli per il manoscritto di Master Nesingwary.",h="Le pagine sparse di Verdi Colline di Rovotorto sono state raccolte nel Chapter I.",kw={"barnil","chapter i","capitolo uno","verdi colline di rovotorto","manoscritto","master nesingwary","pagine sparse","rovotorto"},sec={{t="Pagine sparse",b="Una raffica attraversò l’accampamento di Master Nesingwary e sparse le pagine del suo manoscritto per tutta Rovotorto. Barnil ne raccolse molte, ma mancavano ancora pagine per tutti e quattro i capitoli. Questo capitolo fa parte del libro che Barnil sta ricomponendo, ed è pronto a riordinare le pagine quando verranno ritrovate."}},faq={{q="Cos’è il Chapter I?",a="Il Chapter I è una delle quattro parti del manoscritto sparso di Master Nesingwary, Verdi Colline di Rovotorto.",al={"verdi colline capitolo uno","libro chapter i","cos’è questo capitolo"}},{q="Chi è Barnil?",a="Barnil sta aiutando a ricomporre il manoscritto di Master Nesingwary e chiede i capitoli quando sono completi.",al={"chi è barnil","chi vuole le pagine","manoscritto di barnil"}},{q="Perché le pagine sono sparse?",a="Una forte raffica di vento attraversò l’accampamento di Master Nesingwary e sparse le pagine del manoscritto per tutta la giungla.",al={"pagine volate via","perché mancano le pagine","pagine del manoscritto"}},{q="Chi ha scritto Verdi Colline di Rovotorto?",a="Master Nesingwary è l’autore di Verdi Colline di Rovotorto, un romanzo che Barnil sta aiutando a ricomporre.",al={"libro di nesingwary","chi ha scritto verdi colline","manoscritto di master nesingwary"}}},fp="40,160,15.305.0,18.115.0,14.109.0,28.117.0,43.104.0"}
P.entries["item:green-hills-of-stranglethorn-chapter-ii"] = {n="Verdi Colline di Rovotorto - Capitolo II",s="Chapter II è una delle quattro parti del manoscritto sparso del maestro Nesingwary, Verdi Colline di Rovotorto. Bisogna recuperare le pagine perché Barnil possa assemblare i capitoli e restituire il libro a Nesingwary.",h="Chapter II è una delle quattro parti del manoscritto sparso del maestro Nesingwary, Verdi Colline di...",kw={"barnil","capitolo 2","chapter ii","verdi colline di rovotorto","manoscritto","nesingwary","pagine sparse","rovotorto"},sec={{t="Pagine sparse",b="Barnil aveva raccolto gran parte del manoscritto quando una folata attraversò l’accampamento del maestro Nesingwary. Le pagine di Chapter II si dispersero per Rovotorto insieme alle altre. Puoi aiutare Barnil a rimettere in ordine i quattro capitoli, poi riportarglieli."}},faq={{q="Cos’è Chapter II?",a="Chapter II è una parte del manoscritto del maestro Nesingwary, Verdi Colline di Rovotorto.",al={"capitolo 2","verdi colline capitolo ii"}},{q="Chi sta raccogliendo i capitoli?",a="Barnil sta raccogliendo e riordinando i capitoli sparsi per il maestro Nesingwary.",al={"chi vuole le pagine","pagine di barnil"}},{q="Perché le pagine sono sparse?",a="Una forte folata di vento attraversò l’accampamento del maestro Nesingwary e sparse le pagine del manoscritto per la giungla.",al={"cos’è successo alle pagine","il vento ha sparso le pagine"}},{q="Cosa devo fare con i capitoli?",a="Raccogli tutti e quattro i capitoli e riportali a Barnil, così potrà riordinarli per il maestro Nesingwary.",al={"dove riportare i capitoli","cosa serve a barnil"}},{q="Chi ha scritto Verdi Colline di Rovotorto?",a="Il maestro Nesingwary è l’autore di Verdi Colline di Rovotorto.",al={"libro di nesingwary","romanzo del maestro nesingwary"}}},fp="41,210,15.253.0,19.93.0,30.81.0,28.116.0,35.97.0,43.68.0"}
P.entries["item:green-hills-of-stranglethorn-chapter-iii"] = {n="Verdi Colline di Rovotorto - Capitolo III",s="Chapter III è una delle quattro parti sparse del manoscritto di Master Nesingwary, Verdi Colline di Rovotorto. Barnil sta raccogliendo le pagine al campo nella Valle di Rovotorto.",h="Chapter III è una delle quattro parti sparse del manoscritto di Master Nesingwary, Verdi Colline di Rovotorto.",kw={"barnil","chapter iii","capitolo tre","verdi colline di rovotorto","manoscritto","nesingwary","pagine sparse","valle di rovotorto"},sec={{t="Pagine sparse",b="Una folata attraversò il campo di Master Nesingwary nella Valle di Rovotorto e sparse le pagine del manoscritto per la giungla. Barnil ne raccolse la maggior parte, ma i quattro capitoli sono ancora incompleti. Sta raccogliendo le pagine per rimettere in ordine il manoscritto."}},faq={{q="Che cos'è Chapter III?",a="Chapter III è una delle quattro parti del manoscritto sparso di Master Nesingwary, Verdi Colline di Rovotorto.",al={"capitolo tre","verdi colline capitolo tre"}},{q="Chi sta raccogliendo le pagine?",a="Barnil sta raccogliendo le pagine sparse e riordinando i capitoli per Master Nesingwary.",al={"chi vuole le pagine","pagine barnil"}},{q="Perché le pagine sono sparse?",a="Una forte folata di vento attraversò il campo di Master Nesingwary e sparse le pagine del manoscritto per la giungla.",al={"che cosa è successo alle pagine","il vento ha sparso le pagine"}},{q="Come si intitola il manoscritto?",a="Il manoscritto si intitola Verdi Colline di Rovotorto.",al={"libro di nesingwary","libro delle verdi colline"}}},fp="42,178,15.266.0,20.117.0,28.90.0,28.114.0,30.58.0"}
P.entries["item:green-hills-of-stranglethorn-chapter-iv"] = {n="Verdi Colline di Rovotorto - Capitolo IV",s="Nella Valle di Rovotorto, Barnil ha bisogno che i capitoli sparsi del manoscritto di Master Nesingwary siano raccolti e rimessi in ordine. Chapter IV è uno dei quattro pezzi necessari per completare il libro.",h="Nella Valle di Rovotorto, Barnil ha bisogno che i capitoli sparsi del manoscritto di Master Nesingwary siano...",kw={"barnil","capitolo quattro","chapter iv","verdi colline di rovotorto","manoscritto","master nesingwary","pagine sparse","valle di rovotorto"},sec={{t="Pagine sparse",b="Una folata di vento ha attraversato l'accampamento di Master Nesingwary e ha sparso pagine del suo romanzo per tutta la giungla. Barnil ne ha raccolte quasi tutte, ma le pagine mancanti devono ancora essere recuperate e ordinate in quattro capitoli. Chapter IV va riunito agli altri tre prima che il manoscritto possa essere restituito a Barnil."}},faq={{q="Che cos'è Chapter IV?",a="Chapter IV è uno dei quattro capitoli del romanzo di Master Nesingwary, Verdi Colline di Rovotorto.",al={"capitolo quattro","verdi colline capitolo iv","libro capitolo 4"}},{q="Chi ha bisogno di questo capitolo?",a="Barnil sta raccogliendo i capitoli del manoscritto di Master Nesingwary e li chiede quando sono stati completati tutti e quattro.",al={"chi vuole chapter iv","a chi dare il capitolo quattro","pagine barnil"}},{q="Perché le pagine sono sparse?",a="Una forte folata di vento ha attraversato l'accampamento di Master Nesingwary e ha sparso pagine del suo manoscritto per tutta la giungla.",al={"perché pagine ovunque","che fine ha fatto il libro","il vento ha sparso le pagine"}},{q="Di cosa parla Verdi Colline di Rovotorto?",a="È un romanzo di Master Nesingwary. I capitoli raccolti servono a completarne il manoscritto.",al={"romanzo nesingwary","libro verdi colline","cos'è il manoscritto"}}},fp="41,192,15.301.0,19.104.0,23.114.0,28.119.0,47.95.0"}
