P.entries["item:grimtotem-horn"] = {n="Corno dei Totem Truce",s="I Corni dei Totem Truce vengono sottratti ai tauren Totem Truce a ovest dell’Accampamento Mojache, a Feralas. Krueg Fendicranio li richiede dopo aver scoperto che la tribù è vicina.",h="I Corni dei Totem Truce vengono sottratti ai tauren Totem Truce a ovest dell’Accampamento Mojache, a Feralas.",kw={"belgrom","accampamento mojache","feralas","totem truce","corno dei totem truce","corni dei totem truce","krueg fendicranio","tauren"},ang={["faction:Horde"]="Da viaggiatore dell’Orda, l’avvertimento di Krueg presenta i Totem Truce come una minaccia per le terre e i villaggi dell’Orda."},sec={{t="Recuperati a Feralas",b="A ovest dell’Accampamento Mojache, i tauren Totem Truce portano questi corni. Krueg Fendicranio ti chiede di portargliene un certo numero dopo aver scoperto che il clan si trova a Feralas. Dice che Belgrom ha messo una taglia sui Totem Truce e ti avverte che sono pericolosi."}},faq={{q="Da dove vengono i Corni dei Totem Truce?",a="I tauren Totem Truce a ovest dell’Accampamento Mojache, a Feralas, portano questi corni.",al={"provenienza dei corni","origine corni totem truce"}},{q="Chi vuole i corni?",a="Krueg Fendicranio, all’Accampamento Mojache, ti chiede di portargli dei Corni dei Totem Truce.",al={"chi vuole i corni","corni krueg"}},{q="Perché Krueg li vuole?",a="Krueg chiede i corni dopo aver scoperto che dei tauren Totem Truce si trovano nelle vicinanze. Dice che Belgrom ha interesse per la tribù e ha messo una taglia su di loro.",al={"perché raccogliere corni","a cosa servono i corni"}},{q="Chi sono i Totem Truce?",a="I Totem Truce sono un clan di tauren che vive a ovest dell’Accampamento Mojache, a Feralas.",al={"chi sono i totem truce","tauren totem truce"}}},fp="14,150,16.239.0,35.65.0,20.74.0,25.151.0,22.70.0"}
