P.entries["item:groddoc-liver"] = {n="Fegato di Groddoc",s="Il Fegato di Groddoc viene dalle scimmie di Feralas. Rhapsody Shindigger ne ha bisogno per preparare una bevanda che spera gli sciolga la lingua su un volo terrificante sopra una palude.",h="Il Fegato di Groddoc viene dalle scimmie di Feralas.",kw={"feralas","groddoc ape","fegato di groddoc","fegato di peloduro","kalimdor kocktail","rhapsody shindigger","stomaco di grifalco"},sec={{t="Un ingrediente amaro",b="Rhapsody Shindigger chiede il Fegato di Groddoc nell'Entroterre, insieme a Roc Gizzards e Ironfur Livers. Vuole distillare i tre ingredienti per ottenere un Kalimdor Kocktail. Dice che la bevanda potrebbe aiutarlo a parlare degli orrori di un volo sopra una palude."}},faq={{q="Da dove vengono i Fegati di Groddoc?",a="I Fegati di Groddoc vengono dai Groddoc Apes di Feralas.",al={"dove trovare il fegato di groddoc","origine del fegato di groddoc"}},{q="Chi vuole il Fegato di Groddoc?",a="Rhapsody Shindigger nell'Entroterre chiede tre Fegati di Groddoc per preparare il suo Kalimdor Kocktail.",al={"chi vuole questo fegato","fegato per rhapsody"}},{q="A cosa serve il Fegato di Groddoc?",a="Rhapsody Shindigger usa il Fegato di Groddoc con Roc Gizzards e Ironfur Livers per preparare un Kalimdor Kocktail.",al={"uso del fegato di groddoc","perché serve il fegato"}},{q="Perché Rhapsody sta preparando la bevanda?",a="Rhapsody dice che gli serve una bevanda più forte prima di poterti raccontare di un volo terrificante sopra una palude.",al={"perché il cocktail","rhapsody vuole una bevanda"}}},fp="13,159,19.254.0,34.49.0,24.99.0,31.100.0,33.103.0"}
