P.entries["item:hammertoe-s-amulet"] = {n="Amuleto di Mazzadito",s="L'Amuleto di Mazzadito è il ricordo di un nano partito alla ricerca del passato di Uldaman. A Maleterre, porta avanti il suo lavoro presso chi lo conosceva.",h="L'Amuleto di Mazzadito è il ricordo di un nano partito alla ricerca del passato di Uldaman.",kw={"amuleto","maleterre","nani","hammertoe","karnik lo storico","prospettore ryedol","pergamene","clan shadowforge","uldaman"},ang={["race:Dwarf"]="Da nano, la ricerca di Hammertoe sulle origini del suo popolo riguarda anche le tue radici. Il suo amuleto porta quel lavoro agli studiosi che lo conoscevano."},sec={{t="L'incarico di un nano",b="Ferito a Maleterre, Hammertoe ti chiede di portare il suo amuleto al Prospettore Ryedol. Hammertoe era alla ricerca delle origini del suo popolo e cercava di impedire al clan Shadowforge di trovare le pergamene. Ryedol conosce il suo lavoro e Hammertoe si fida di lui, lasciandogli decidere il da farsi."},{t="A Forgiardente",b="Dopo aver saputo cos'è accaduto a Hammertoe, Ryedol ti manda da Karnik lo Storico a Forgiardente. Karnik e Hammertoe avevano collaborato per trovare antichi manufatti perduti a Uldaman. L'amuleto porta il loro lavoro nelle mani di Karnik, che capisce che c'è in gioco ben più del dolore per la perdita del suo compagno."}},faq={{q="Chi era Hammertoe?",a="Hammertoe era un nano alla ricerca delle origini del suo popolo a Uldaman. Cercava anche di impedire al clan Shadowforge di trovare le pergamene.",al={"hammertoe nano","chi è hammertoe","storia di hammertoe"}},{q="Perché Hammertoe mi dà il suo amuleto?",a="Hammertoe ti chiede di portare l'amuleto al Prospettore Ryedol a Maleterre. Ryedol conosce la ricerca di Hammertoe e può decidere cosa fare dopo.",al={"perché l'amuleto","perché l'amuleto di mazzadito","cosa fare con l'amuleto"}},{q="Chi è il Prospettore Ryedol?",a="Il Prospettore Ryedol è il nano a cui Hammertoe affida il suo amuleto e il suo lavoro a Uldaman.",al={"chi è ryedol","il prospettore"}},{q="Perché l'amuleto è importante?",a="L'amuleto apparteneva a Hammertoe e rappresenta il suo lavoro a Uldaman, dove cercava le origini del suo popolo. Ryedol e Karnik lo Storico conoscono quel lavoro.",al={"importanza dell'amuleto","cosa ha di speciale","a cosa serve l'amuleto"}},{q="Chi è Karnik lo Storico?",a="Karnik lo Storico si trova a Forgiardente e collaborava con Hammertoe per trovare antichi manufatti perduti a Uldaman. Ryedol ti manda da lui con l'amuleto.",al={"chi è karnik","lo storico"}},{q="Cosa cercava di impedire Hammertoe?",a="Hammertoe cercava di impedire al clan Shadowforge di trovare le pergamene a Uldaman.",al={"obiettivo degli shadowforge","perché fermare gli shadowforge","pergamene a uldaman"}}},fp="18,150,18.291.0,12.285.0,18.143.0,38.147.0,25.88.0,28.149.0,24.136.0,34.82.0"}
P.entries["item:hand-of-dagun"] = {n="Artiglio di Dagun",s="L'Artiglio di Dagun è una reliquia che Gerrig Morsaossa cerca a Forgiardente. È uno dei tre oggetti che chiede in cambio del Compendio di Yagyin.",h="L'Artiglio di Dagun è una reliquia che Gerrig Morsaossa cerca a Forgiardente.",kw={"dagun","gerrig morsaossa","artiglio di dagun","cuore dell'immortalità","veleno","reliquia","stella di xil'yeh","compendio di yagyin"},ang={["faction:Alliance"]="Per l'Alleanza, la richiesta di Gerrig Morsaossa offre l'occasione di contribuire all'inizio di un nuovo capitolo del suo ordine."},sec={{t="Una reliquia per Morsaossa",b="Gerrig Morsaossa chiede l'Artiglio di Dagun insieme ad altre due reliquie. Gli servono tutte e tre per darti una copia del Compendio di Yagyin, un testo legato all'inizio di un nuovo capitolo del suo ordine."}},faq={{q="Cos'è l'Artiglio di Dagun?",a="L'Artiglio di Dagun è una reliquia che Gerrig Morsaossa chiede insieme alla Stella di Xil'yeh e al Cuore dell'Immortalità.",al={"artiglio di dagun","cos'è l'artiglio"}},{q="Chi vuole l'Artiglio di Dagun?",a="Gerrig Morsaossa, a Forgiardente, ti chiede di portargli l'Artiglio di Dagun e altre due reliquie.",al={"chi vuole l'artiglio di dagun","artiglio morsaossa","chi ne ha bisogno"}},{q="Perché Gerrig Morsaossa ne ha bisogno?",a="Gerrig ha bisogno dell'Artiglio di Dagun come una delle tre reliquie che chiede prima di darti una copia del Compendio di Yagyin.",al={"perché morsaossa lo vuole","perché serve l'artiglio","a cosa serve"}},{q="Cosa fa l'Artiglio di Dagun?",a="Si dice che l'Artiglio di Dagun contenga un veleno che muta la vittima in un membro di un'antica razza.",al={"poteri dell'artiglio di dagun","cosa fa","artiglio avvelenato"}}},fp="13,138,20.193.0,26.100.0,28.90.0,33.110.0,31.97.1"}
