P.entries["item:hand-of-iruxos"] = {n="Mano di Iruxos",s="La Mano di Iruxos è un macabro artefatto capace di aprire portali demoniaci e chiudere quelli che ha aperto. Taiga Chioma Saggia ne ha bisogno per contribuire a bandire i portali alla Congrega di Mannoroc.",h="La Mano di Iruxos è un macabro artefatto capace di aprire portali demoniaci e chiudere quelli che ha aperto.",kw={"lame ardenti","portali demoniaci","mano di iruxos","iruxos","congrega di mannoroc","predombra","taiga chioma saggia"},sec={{t="Una vista raccapricciante",b="A Predombra, Taiga Chioma Saggia ti consegna la Mano di Iruxos e ti chiede di portarla alla Congrega di Mannoroc. Gli adepti della setta delle Lame Ardenti hanno aperto portali che portano demoni nel mondo. La mano può chiudere i portali che ha aperto e Taiga ha bisogno del suo potere per arginare la crescente minaccia demoniaca."}},faq={{q="Cos'è la Mano di Iruxos?",a="È una macabra reliquia che apre portali demoniaci e può chiudere quelli che ha aperto.",al={"mano di iruxos"}},{q="Chi mi consegna la Mano di Iruxos?",a="Taiga Chioma Saggia, a Predombra, ti consegna la Mano di Iruxos e ti chiede di usarla contro i portali alla Congrega di Mannoroc.",al={"chi ha la mano","mano di taiga"}},{q="Dove uso la Mano di Iruxos?",a="Taiga Chioma Saggia ti chiede di usare la Mano di Iruxos per bandire i portali demoniaci alla Congrega di Mannoroc.",al={"posizione della mano","dove usare la mano"}},{q="Perché ci sono demoni alla Congrega di Mannoroc?",a="Gli adepti della setta delle Lame Ardenti alla Congrega di Mannoroc hanno aperto portali che portano demoni nel mondo.",al={"demoni a mannoroc","perché ci sono demoni"}},{q="La Mano di Iruxos può chiudere i portali?",a="La Mano di Iruxos può chiudere i portali demoniaci che ha aperto.",al={"chiudere i portali","mano dei portali"}}},fp="14,172,16.299.0,27.82.0,32.127.0,34.94.0,39.94.0,37.59.0"}
