P.entries["item:hatecrest-naga-scale"] = {n="Scaglia di Naga Crestaostile",s="Le scaglie dei Hatecrest Naga si ricavano dai naga che minacciano l'Isola di Sardor, a Feralas. Latronicus Lanciargentea, alla Roccaforte di Piumaluna, le vuole per indebolire la presenza dei naga e studiare cosa se ne possa ricavare.",h="Le scaglie dei Hatecrest Naga si ricavano dai naga che minacciano l'Isola di Sardor, a Feralas.",kw={"roccaforte di piumaluna","scaglia di naga crestaostile","scaglie hatecrest","latronicus lanciargentea","naga","pratt","isola di sardor"},ang={["race:NightElf"]="Da elfo della Notte, aiuti Latronicus a proteggere gli interessi della Roccaforte di Piumaluna sull'Isola di Sardor. Dice che il suo popolo cerca la pace, ma agirà per difendere ciò che gli appartiene."},sec={{t="Scaglie per Piumaluna",b="Latronicus Lanciargentea ti chiede di portare dieci Hatecrest Naga Scales alla Roccaforte di Piumaluna. Teme che i naga cerchino di assicurarsi l'Isola di Sardor, quindi vuole indebolirne la presenza prima che la minaccia cresca. Le scaglie devono essere in buone condizioni. Una volta ricevute, intende inviarle a Pratt perché le studi e valuti un possibile impiego nell'artigianato."}},faq={{q="A cosa servono le Hatecrest Naga Scales?",a="Latronicus Lanciargentea vuole dieci Hatecrest Naga Scales in buone condizioni per indebolire la presenza dei naga sull'Isola di Sardor. Intende anche inviarle a Pratt per capire se si possano usare nell'artigianato.",al={"perché le scaglie","uso delle scaglie hatecrest","scopo delle scaglie"}},{q="Chi vuole le scaglie?",a="Latronicus Lanciargentea, alla Roccaforte di Piumaluna, chiede dieci Hatecrest Naga Scales.",al={"chi ha bisogno delle scaglie","scaglie latronicus","per chi sono le scaglie"}},{q="Perché Piumaluna vuole indebolire i naga?",a="Latronicus teme che i naga Hatecrest cerchino di assicurarsi l'Isola di Sardor, quindi vuole indebolirne la presenza prima che ci riescano.",al={"perché combattere gli hatecrest","minaccia dei naga","perché l'isola di sardor"}},{q="Cosa potrebbe fare Pratt con le scaglie?",a="Latronicus intende inviare le scaglie a Pratt, che potrebbe riuscire a ricavarne qualcosa di utile per l'artigianato.",al={"scaglie pratt","artigianato con le scaglie","scaglie per l'artigianato"}}},fp="20,205,22.331.0,35.182.0,21.82.0,45.127.0,36.98.0"}
P.entries["item:hatefury-claw"] = {n="Artiglio di Furiatorva",s="Un Artiglio di Furiatorva si ottiene dai satiri Hatefury a est di Nijel’s Point, in Desolanda. Kreldig Ungor raccoglie artigli e corna per un mago gnomo a Kharanos.",h="Un Artiglio di Furiatorva si ottiene dai satiri Hatefury a est di Nijel’s Point, in Desolanda.",kw={"artiglio di furiatorva","corno di furiatorva","satiro hatefury","kreldig ungor","leftwitch","presidio di nijel","reagenti","sargeron"},ang={["class:Mage"]="Da mago, potresti riconoscere la necessità pratica dietro l’elenco di Leftwitch: Kreldig raccoglie artigli e corna come reagenti.",["race:Gnome"]="Da gnomo, la richiesta di Leftwitch ti arriva tramite Kreldig Ungor, che raccoglie reagenti in Desolanda per il mago di Kharanos."},sec={{t="Un elenco di reagenti",b="Kreldig Ungor è arrivato a Desolanda con un elenco di reagenti inviatogli da Leftwitch, un mago gnomo di Kharanos. I satiri Hatefury tra le rovine di Sargeron, a est di Nijel’s Point, portano gli artigli e le corna che gli servono. Porta i materiali raccolti a Kreldig e lui si occuperà del prossimo elemento dell’elenco."}},faq={{q="Chi vuole gli Artigli di Furiatorva?",a="Kreldig Ungor raccoglie Artigli di Furiatorva e corna per Leftwitch, un mago gnomo di Kharanos.",al={"chi vuole gli artigli","acquirente di artigli"}},{q="Da dove provengono gli Artigli di Furiatorva?",a="I satiri Hatefury nelle rovine di Sargeron, a est di Nijel’s Point in Desolanda, portano gli artigli.",al={"provenienza degli artigli","posizione degli artigli"}},{q="Perché Kreldig raccoglie gli artigli?",a="Kreldig raccoglie reagenti da un elenco inviato da Leftwitch, un mago gnomo di Kharanos.",al={"perché gli artigli","reagenti per i ricostruttori"}},{q="Cos’altro serve a Kreldig?",a="Per l’elenco di Leftwitch, a Kreldig servono anche Corna Hatefury, oltre agli Artigli di Furiatorva.",al={"quali altri reagenti","anche le corna"}}},fp="13,145,20.297.0,25.87.0,34.92.0,32.86.0,28.78.0"}
